<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import WorkspaceShell from '../components/WorkspaceShell.vue'
import PublicVideoCard from '../components/PublicVideoCard.vue'
import { publicApi, durationLabel } from '../api/public'
import type { PublicVideo } from '../api/public'
import type { SignedMedia } from '../api/creator'
import { formatTime } from '../api/creator'
import { useStudioError } from '../composables/useStudioError'
const id = String(useRoute().params.id); const explain = useStudioError(); const video = ref<PublicVideo>(); const media = ref<SignedMedia>(); const player = ref<HTMLVideoElement>(); const loading = ref(false); const signing = ref(false); const favoriteBusy = ref(false); const favorited = ref<boolean>(); const liked = ref<boolean>(); const likeBusy = ref(false); const error = ref(''); const mediaError = ref(''); const favoriteError = ref(''); const notice = ref(''); const related = ref<PublicVideo[]>([]); const relatedLoading = ref(false); const relatedError = ref(''); let activeRequest: AbortController | undefined; let mediaRequest: AbortController | undefined; let relatedRequest: AbortController | undefined; const lifetime = new AbortController()
function clearMedia() { player.value?.pause(); player.value?.removeAttribute('src'); player.value?.load(); media.value = undefined }
async function load() { activeRequest?.abort(); mediaRequest?.abort(); relatedRequest?.abort(); signing.value = false; clearMedia(); related.value = []; relatedError.value = ''; const controller = new AbortController(); activeRequest = controller; loading.value = true; error.value = ''; video.value = undefined; try { const result = await publicApi.get(id, controller.signal); if (!controller.signal.aborted) { video.value = result; void loadRelated(result) } } catch (failure) { if (!controller.signal.aborted) error.value = explain(failure) } finally { if (!controller.signal.aborted) loading.value = false } }
async function loadRelated(current: PublicVideo) { relatedRequest?.abort(); const controller = new AbortController(); relatedRequest = controller; relatedLoading.value = true; relatedError.value = ''; try { const result = await publicApi.list('', current.categoryId, 1, controller.signal); if (!controller.signal.aborted) related.value = result.items.filter(item => item.id !== current.id).slice(0, 3) } catch (failure) { if (!controller.signal.aborted) relatedError.value = explain(failure) } finally { if (!controller.signal.aborted) relatedLoading.value = false } }
async function recordView() {
  if (sessionStorage.getItem(`frame-viewed-${id}`)) return
  sessionStorage.setItem(`frame-viewed-${id}`, '1')
  try {
    const result = await publicApi.view(id)
    if (!lifetime.signal.aborted && video.value) video.value = { ...video.value, viewCount: result.viewCount }
  } catch { /* views are best-effort */ }
}
async function play() { if (!video.value || signing.value || loading.value) return; mediaRequest?.abort(); const controller = new AbortController(); mediaRequest = controller; signing.value = true; mediaError.value = ''; clearMedia(); void recordView(); try { const result = await publicApi.media(id, 'SOURCE', controller.signal); if (!controller.signal.aborted) media.value = result } catch (failure) { if (!controller.signal.aborted) mediaError.value = explain(failure) } finally { if (!controller.signal.aborted) signing.value = false } }
async function likeState() { try { const result = await publicApi.likeState(id, lifetime.signal); if (!lifetime.signal.aborted) liked.value = result.liked } catch { if (!lifetime.signal.aborted) liked.value = undefined } }
async function toggleLike() { if (liked.value === undefined || likeBusy.value) return; const add = !liked.value; likeBusy.value = true; try { await publicApi.like(id, add); if (!lifetime.signal.aborted) { liked.value = add; if (video.value) video.value = { ...video.value, likeCount: Math.max(0, video.value.likeCount + (add ? 1 : -1)) } } } catch { /* best effort */ } finally { if (!lifetime.signal.aborted) likeBusy.value = false } }
async function favoriteState() { favoriteBusy.value = true; favoriteError.value = ''; try { const result = await publicApi.favoriteState(id, lifetime.signal); if (!lifetime.signal.aborted) favorited.value = result.favorited } catch (failure) { if (!lifetime.signal.aborted) { favorited.value = undefined; favoriteError.value = explain(failure) } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
async function toggleFavorite() { if (favoriteBusy.value || favorited.value === undefined) return; const add = !favorited.value; favoriteBusy.value = true; favoriteError.value = ''; notice.value = ''; try { await publicApi.favorite(id, add); if (!lifetime.signal.aborted) { favorited.value = add; if (video.value) video.value = { ...video.value, favoriteCount: Math.max(0, video.value.favoriteCount + (add ? 1 : -1)) }; notice.value = add ? '已加入收藏。' : '已取消收藏。' } } catch (failure) { if (!lifetime.signal.aborted) { favoriteError.value = `${explain(failure)}。正在核对收藏状态。`; favorited.value = undefined; await favoriteState() } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
onMounted(() => { if (/^[1-9]\d{0,18}$/.test(id)) { void load(); void favoriteState(); void likeState() } else error.value = '作品编号无效' }); onBeforeUnmount(() => { lifetime.abort(); activeRequest?.abort(); mediaRequest?.abort(); relatedRequest?.abort(); clearMedia() })
</script>
<template><WorkspaceShell><RouterLink class="back-link" to="/">← 发现作品</RouterLink><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert" /><p v-if="loading" class="empty-state" role="status">正在读取作品…</p><el-button v-if="error" @click="load">重新读取</el-button><template v-if="video"><section class="watch-screen" aria-label="视频播放器"><video v-if="media" ref="player" :src="media.url" controls playsinline preload="metadata" @error="mediaError = '视频无法加载或链接已过期，请重新获取播放地址。'" /><div v-else class="watch-prompt"><span>{{ durationLabel(video.durationMillis) }}</span><p>准备观看《{{ video.title }}》</p><el-button :loading="signing" @click="play">加载视频</el-button></div></section><el-alert v-if="mediaError" :title="mediaError" type="error" :closable="false" role="alert" /><div class="watch-toolbar"><span>分类：{{ video.categoryName }} · 作者：{{ video.authorName }}</span><el-button :loading="signing" @click="play">重新获取播放地址</el-button></div><div class="watch-heading"><div><h1>{{ video.title }}</h1><p class="muted"><RouterLink :to="`/authors/${video.authorId}`">{{ video.authorName }}</RouterLink> · {{ video.viewCount }} 次播放 · {{ video.favoriteCount }} 收藏 · {{ video.likeCount }} 赞 · 发布于 {{ formatTime(video.publishedAt) }}</p></div><div class="inline-actions"><el-button :loading="likeBusy" :disabled="liked === undefined" @click="toggleLike">{{ liked ? '已赞' : '点赞' }}</el-button><el-button :loading="favoriteBusy" :disabled="favorited === undefined" @click="toggleFavorite">{{ favorited ? '取消收藏' : '收藏作品' }}</el-button></div></div><el-alert v-if="favoriteError" :title="favoriteError" type="error" :closable="false" role="alert" /><el-button v-if="favorited === undefined" :disabled="favoriteBusy" @click="favoriteState">查询收藏状态</el-button><p v-if="notice" role="status" class="muted">{{ notice }}</p><p class="video-description">{{ video.description || '作者未填写简介。' }}</p><p v-if="media" class="muted">播放地址到期：{{ formatTime(media.expiresAt) }}。过期后可重新获取。</p><section v-if="relatedLoading || related.length || relatedError" class="studio-panel related-section"><div class="related-heading"><h2>同类作品</h2><RouterLink :to="{ path: '/', query: { category: video.categoryId } }">查看全部 →</RouterLink></div><p v-if="relatedLoading" class="muted" role="status">正在读取同类作品…</p><p v-else-if="relatedError" class="muted">同类作品暂时无法加载。</p><div v-else class="public-video-grid related-grid"><PublicVideoCard v-for="item in related" :key="item.id" :video="item" /></div></section></template></WorkspaceShell></template>
